/**
 * 清洗列标签并还原枚举中文。
 *
 * 自动生成的 MODULES 元数据里，带选项的列把「选项映射」塞进了 label 后缀，
 * 形如 "单据类型:1=销货单,2=零售单"（分隔符混用 , 与 :）；同时枚举 label 很多
 * 直接是数字本身（{value:"1",label:"1"}）。这导致：
 *   1) 表头显示成携带 code 解释的脏文本，不全是中文；
 *   2) 单元格与表单下拉都显示数字而非中文。
 * 这里把前缀作为干净中文表头，并从后缀解析 code→name 映射回写到枚举 label。
 * 此外对仍是纯英文蛇形字段名的标签做有限回退翻译，避免表头显示英文。
 */
const RAW_LABEL_DICT: Record<string, string> = {
  id: '编号',
  admin_id: '操作人',
  createtime: '创建时间',
  updatetime: '更新时间',
  deletetime: '删除时间',
  status: '状态',
  type: '类型',
  remark: '备注',
  note: '备注',
  sort: '排序',
  goods_code: '商品编号',
  code: '编号',
  name: '名称',
  number: '数量',
  price: '单价',
  money: '金额',
  suppliers_id: '供应商',
  customers_id: '客户',
  stores_id: '仓库',
  unit_id: '单位',
};

function cleanLabel(raw: string): { label: string; map: Record<string, string> | null } {
  const idx = raw.indexOf(':');
  if (idx !== -1) {
    const prefix = raw.slice(0, idx).trim();
    const suffix = raw.slice(idx + 1);
    const map: Record<string, string> = {};
    const re = /(\d+)\s*[=：:]\s*([^,，:]+)/g;
    let m: RegExpExecArray | null;
    while ((m = re.exec(suffix))) map[m[1]] = m[2].trim();
    if (Object.keys(map).length) return { label: prefix, map };
  }
  if (/^[a-z_]+$/.test(raw) && RAW_LABEL_DICT[raw]) return { label: RAW_LABEL_DICT[raw], map: null };
  return { label: raw, map: null };
}

/** 清洗一列元数据：表头去脏后缀 + 枚举数字回写为中文 */
function normalizeColumn(col: ColumnMeta): ColumnMeta {
  const { label, map } = cleanLabel(col.label);
  let enumv = col.enum;
  if (enumv && map) {
    enumv = enumv.map((e) => {
      if (e && e.value != null && e.label === String(e.value) && map[String(e.value)] != null) {
        return { value: e.value, label: map[String(e.value)] };
      }
      return e;
    });
  }
  return { ...col, label, enum: enumv };
}

function normalizeColumns(cols: ColumnMeta[]): ColumnMeta[] {
  return cols.map(normalizeColumn);
}

// 模块加载时一次性清洗所有模块列（源生成数据携带 code 解释与数字枚举），
// 使 findModule 与直接引用 MODULES 的页面都拿到干净中文。
MODULES.forEach((m) => {
  m.columns = normalizeColumns(m.columns);
});
GROUPED_MODULES.forEach((g) => {
  g.modules.forEach((m) => {
    m.columns = normalizeColumns(m.columns);
  });
});

export function findModule(key: string): ModuleMeta | undefined {
  return MODULES.find((m) => m.key === key);
}
